files.content:
:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --accent: #f5a623;
  --text: #e0e0e0;
  --bar-bg: #3a3a55;
  --bar-fill: #4caf50;
  --bar-low: #e74c3c;
  --focus: #f5a623;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.pet-card {
  background: var(--card);
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 1.5rem;
  color: var(--accent);
  letter-spacing: 0.05em;
}

.pet-stage {
  display: flex;
  justify-content: center;
  margin-bottom: 1rem;
}

.pet {
  width: 120px;
  height: 120px;
  position: relative;
  animation: bob 2s ease-in-out infinite;
}

@keyframes bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.pet-body {
  width: 100%;
  height: 100%;
  background: var(--accent);
  border-radius: 30% 30% 40% 40%;
  position: absolute;
  top: 0;
  left: 0;
  box-shadow: inset -8px -8px 0 rgba(0,0,0,0.15);
}

.pet-face {
  position: absolute;
  top: 30%;
  left: 50%;
  transform: translateX(-50%);
  width: 70%;
  height: 50%;
}

.eye {
  width: 14px;
  height: 14px;
  background: #1e1e2f;
  border-radius: 50%;
  position: absolute;
  top: 0;
}

.eye.left { left: 10%; }
.eye.right { right: 10%; }

.mouth {
  width: 30px;
  height: 10px;
  border: 3px solid #1e1e2f;
  border-top: none;
  border-radius: 0 0 20px 20px;
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
}

.mood {
  font-size: 1.2rem;
  margin-bottom: 1.5rem;
  font-weight: 600;
  min-height: 1.6em;
  transition: color 0.3s;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
  margin-bottom: 2rem;
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

.stat-label {
  flex: 0 0 90px;
  text-align: left;
  font-size: 1rem;
  font-weight: 500;
}

.bar {
  flex: 1;
  height: 20px;
  background: var(--bar-bg);
  border-radius: 10px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: var(--bar-fill);
  border-radius: 10px;
  transition: width 0.3s ease, background 0.3s;
}

.bar-fill.low {
  background: var(--bar-low);
}

.controls {
  display: flex;
  gap: 0.8rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  flex: 1;
  min-width: 90px;
  padding: 0.8rem 1rem;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--bg);
  background: var(--accent);
  border: none;
  border-radius: 0.8rem;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  font-family: inherit;
}

.btn:hover {
  background: #ffb84d;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
  background: #d48a1a;
}

@media (max-width: 400px) {
  .pet-card {
    padding: 1.5rem 1rem;
  }
  .stat-label {
    flex: 0 0 70px;
    font-size: 0.9rem;
  }
  .btn {
    font-size: 1rem;
    padding: 0.7rem 0.5rem;
  }
}

(function() {
  'use strict';

  const state = {
    hunger: 70,
    happiness: 70,
    energy: 70
  };

  const moodEl = document.getElementById('mood');
  const bars = {
    hunger: { bar: document.getElementById('hunger-bar'), fill: document.getElementById('hunger-fill') },
    happiness: { bar: document.getElementById('happiness-bar'), fill: document.getElementById('happiness-fill') },
    energy: { bar: document.getElementById('energy-bar'), fill: document.getElementById('energy-fill') }
  };

  function clamp(v) {
    return Math.max(0, Math.min(100, v));
  }

  function updateBars() {
    for (const key in bars) {
      const val = Math.round(state[key]);
      bars[key].bar.setAttribute('aria-valuenow', val);
      bars[key].fill.style.width = val + '%';
      bars[key].fill.classList.toggle('low', val < 30);
    }
  }

  function updateMood() {
    const avg = (state.hunger + state.happiness + state.energy) / 3;
    let mood;
    if (avg >= 75) mood = 'Ecstatic';
    else if (avg >= 55) mood = 'Happy';
    else if (avg >= 35) mood = 'Okay';
    else if (avg >= 15) mood = 'Sad';
    else mood = 'Miserable';
    moodEl.textContent = 'Mood: ' + mood;
  }

  function render() {
    updateBars();
    updateMood();
  }

  function feed() {
    state.hunger = clamp(state.hunger + 20);
    state.happiness = clamp(state.happiness + 5);
    state.energy = clamp(state.energy - 5);
    render();
  }

  function play() {
    state.happiness = clamp(state.happiness + 20);
    state.energy = clamp(state.energy - 15);
    state.hunger = clamp(state.hunger - 10);
    render();
  }

  function sleep() {
    state.energy = clamp(state.energy + 30);
    state.hunger = clamp(state.hunger - 5);
    state.happiness = clamp(state.happiness - 5);
    render();
  }

  document.getElementById('feed').addEventListener('click', feed);
  document.getElementById('play').addEventListener('click', play);
  document.getElementById('sleep').addEventListener('click', sleep);

  // Passive decay every 5 seconds
  setInterval(function() {
    state.hunger = clamp(state.hunger - 1);
    state.happiness = clamp(state.happiness - 1);
    state.energy = clamp(state.energy - 1);
    render();
  }, 5000);

  render();
})();
